// Transmission bank (v0.23.0): every line a faction can say, by cause, by
// planet and by big moment. The data (transmission_bank.cpp) is GENERATED by
// tools/transmissions/make_bank.pl from tools/transmissions/*.txt -- edit the
// .txt files, rerun the script. Lines may contain {planet}.
#pragma once
#include <stdint.h>
#include "game_state.h"

// Why a faction is calling (order = the .txt files' causes).
enum TxCause : uint8_t {
  TXC_TOOK,     // you took their planet
  TXC_BETRAY,   // you took it while on good terms (Favorable+)
  TXC_RIVAL,    // you took a planet from their rival
  TXC_PAID,     // you bought one of their planets
  TXC_DEAL,     // you made a negotiated deal with them
  TXC_WALKOUT,  // you left their negotiation
  TXC_KEPT,     // you kept a promise to them
  TXC_BROKE,    // you broke one
  TXC_COURTED,  // 3.1-dev.49: you won / bought a world from their RIVAL by talks or Credits
  TXC_COUNT
};

// Big moments (order = big.txt). Each fires at most once per player per game.
enum TxBig : uint8_t {
  TXB_FIRSTBLOOD,   // first planet captured in battle this game -- its faction speaks
  TXB_SEAT,         // a faction's seat of power falls -- that faction speaks
  TXB_CORE,         // your first Core world -- its faction speaks
  TXB_ALLIED,       // you reach Allied -- that faction welcomes you
  TXB_BETRAYAL,     // you capture from a faction you're Favorable+ with
  TXB_OATHBREAKER,  // you break a promise to a faction you're Allied with
  TXB_FLEET,        // you destroy another player's fleet -- their faction answers
  TXB_LASTROUND,    // the final round begins -- your own faction speaks
  TXB_COUNT
};

struct TxBucket { uint16_t start; uint8_t count; };

extern const uint16_t TX_LINE_COUNT;
extern const char *const TX_LINES[];
extern const TxBucket TX_CAUSE_BUCKETS[NUM_FACTIONS][TXC_COUNT];
extern const TxBucket TX_PLANET_BUCKETS[NUM_FACTIONS][NUM_PLANETS];
extern const TxBucket TX_BIG_BUCKETS[TXB_COUNT][NUM_FACTIONS];
